    // MARK: 4. Les diablotins

    /// Un œil retracé : centre (unités image), longueur (px image), inclinaison
    /// sous l'horizontale (rad), ratio longueur/hauteur MESURÉ, et le sens
    /// (+1 œil gauche : le nez est à droite ; −1 œil droit).
    struct Eye {
        let c: CGPoint
        let len: CGFloat
        let tilt: Double
        let ratio: CGFloat
        let inward: CGFloat
    }

    /// Le limbe d'une sphère : cercle AJUSTÉ sur la photo, plus le PROFIL
    /// angulaire de son rim MESURÉ dans l'image (72 cases de 5°, angle 0 = +x,
    /// y vers le bas) et le RAYON du rim par case (fraction de r). Le
    /// liseré-diamant s'allume exactement là où la photo est allumée : il ne
    /// peut PAS dessiner un cercle complet, par construction.
    struct Limb {
        let c: CGPoint
        let r: CGFloat
        let prof: [Double]
        let ridge: [Double]

        init(c: CGPoint, r: CGFloat, prof: String, ridge: String) {
            self.c = c
            self.r = r
            // ⚠️ Les relevés sont LISSÉS angulairement (gaussienne circulaire,
            // σ ≈ 2 cases = 10°) avant tout usage. Sans ça, le zigzag d'une
            // case à l'autre traverse le seuil vingt fois de suite et le
            // liseré se lit comme une CHAÎNETTE PERLÉE — le défaut relevé au
            // round précédent. Un relevé lissé ne peut plus perler.
            self.prof = Limb.smoothRing(prof.split(separator: ",").compactMap { Double($0) })
            self.ridge = Limb.smoothRing(ridge.split(separator: ",").compactMap { Double($0) })
        }

        static func smoothRing(_ v: [Double]) -> [Double] {
            guard v.count > 8 else { return v }
            let k: [Double] = [0.06, 0.24, 0.40, 0.24, 0.06]
            let n = v.count
            return (0..<n).map { i in
                var s = 0.0
                for (j, w) in k.enumerated() { s += w * v[((i + j - 2) % n + n) % n] }
                return s
            }
        }
    }

    /// Un diablotin complet.
    struct Imp {
        let eyes: [Eye]
        /// Gris 0-255 du corps autour des yeux (les caches).
        let body: Double
        let limb: Limb?
        let phase: Double
        let blinkPeriod: Double
        let sleeper: Bool
        /// Amplitude du regard (fraction de la largeur d'œil).
        let gaze: CGFloat
        /// Fumée noire qui monte des épaules (les gros seulement).
        let smoke: Bool
        /// Mèches de brume au-dessus de la tête : 1-4 pour les gros, 0-1 petits.
        let filaments: Int
        /// Hauteur de montée des mèches (pt).
        let filamentRise: CGFloat
    }

