        Imp(eyes: [Eye(c: CGPoint(x: 0.2070, y: 0.8591), len: 26, tilt: 0.520, ratio: 2.23, inward: 1),
                   // Œil droit RECALÉ À LA MAIN après revue visuelle : la mesure
