    private static func small(_ lx: Double, _ ly: Double, _ rx: Double, _ ry: Double,
                              w: CGFloat, body: Double, phase: Double,
                              blink: Double, fil: Int) -> Imp {
        Imp(eyes: [Eye(c: CGPoint(x: lx, y: ly), len: w, tilt: 0.46, ratio: 2.5, inward: 1),
                   Eye(c: CGPoint(x: rx, y: ry), len: w, tilt: 0.46, ratio: 2.5, inward: -1)],
            body: body, limb: nil, phase: phase, blinkPeriod: blink,
            sleeper: true, gaze: 0.11, smoke: false,
            filaments: fil, filamentRise: 14)
    }

