    static let controlFeather: CGFloat = 22
    /// Plancher d'assourdissement sous une boîte (0 = éteint, 1 = intact).
    static let controlFloor: Double = 0.45
    static let controlFloorSoft: Double = 0.62

    // MARK: Utilitaires

    /// Le point de la veine à l'abscisse u ∈ [0,1] (interpolation linéaire).
    static func vein(_ u: CGFloat) -> CGPoint {
        let k = min(max(u, 0), 1) * CGFloat(veinPts.count - 1)
        let i = min(Int(k), veinPts.count - 2)
        let f = k - CGFloat(i)
        let a = veinPts[i], b = veinPts[i + 1]
        return CGPoint(x: a.x + (b.x - a.x) * f, y: a.y + (b.y - a.y) * f)
    }

    /// La distance d'un point (unités image) à la polyligne de la veine, dans
    /// l'espace corrigé de l'aspect — exactement la même mesure que le shader.
    static func veinDistance(_ p: CGPoint) -> CGFloat {
        let a = refSize.width / refSize.height
        let q = CGPoint(x: p.x * a, y: p.y)
        var best = CGFloat.greatestFiniteMagnitude
        for i in 0..<(veinPts.count - 1) {
            let s = CGPoint(x: veinPts[i].x * a, y: veinPts[i].y)
            let e = CGPoint(x: veinPts[i + 1].x * a, y: veinPts[i + 1].y)
            let ab = CGPoint(x: e.x - s.x, y: e.y - s.y)
            let ap = CGPoint(x: q.x - s.x, y: q.y - s.y)
            let dd = max(ab.x * ab.x + ab.y * ab.y, 1e-9)
            let h = min(max((ap.x * ab.x + ap.y * ab.y) / dd, 0), 1)
            best = min(best, hypot(ap.x - ab.x * h, ap.y - ab.y * h))
        }
        return best
    }

    /// Les POINTS D'ATTERRISSAGE des éclats : les grains les plus brillants
    /// MESURÉS sur la photo qui se trouvent dans la bande de la veine. Un
    /// diamant ne peut donc se poser que sur de la matière réellement claire —
    /// jamais dans le vide, par construction.
    static let landingSpots: [CGPoint] = {
        var picks = glimmers
            .filter { $0.z > 0.115 && veinDistance(CGPoint(x: CGFloat($0.x),
                                                          y: CGFloat($0.y))) < 0.055 }
            .map { CGPoint(x: CGFloat($0.x), y: CGFloat($0.y)) }
        picks.append(contentsOf: knots.map(\.p))
        return picks
    }()

    /// Hachage déterministe : la scène est identique à chaque lancement.
    static func hash(_ i: Int, _ salt: Double) -> Double {
        let v = sin(Double(i) * 127.1 + salt * 311.7) * 43758.5453
        return v - v.rounded(.down)
    }

    static func lerp(_ r: ClosedRange<Double>, _ u: Double) -> Double {
        r.lowerBound + (r.upperBound - r.lowerBound) * u
    }

    static func lerp(_ r: ClosedRange<CGFloat>, _ u: Double) -> CGFloat {
        r.lowerBound + (r.upperBound - r.lowerBound) * CGFloat(u)
    }

    /// L'assourdissement au point écran p : 1 loin des contrôles, `floor`
    /// dessous, fondu sur `controlFeather`. Seules les boîtes comptent.
    static func controlDim(_ p: CGPoint, w: CGFloat, h: CGFloat,
                           floor f: Double) -> Double {
        var d = 1.0
        for b in controlBoxes {
            let dx = max(b.minX * w - p.x, p.x - b.maxX * w, 0)
            let dy = max(b.minY * h - p.y, p.y - b.maxY * h, 0)
            let x = min(max(max(dx, dy) / controlFeather, 0), 1)
            d = min(d, f + (1 - f) * Double(x * x * (3 - 2 * x)))
        }
        return d
    }

    /// Le chemin d'un œil FÉROCE : deux cubiques lisses fermées par un petit
    /// chapeau au coin EXTERNE (épais, ~27 % de la hauteur), fuselage vers une
    /// pointe INTERNE qui plonge de 25-30° vers l'arête du nez. Le ventre est
    /// à ~31 % du côté externe — c'est ça, la férocité : jamais une feuille
    /// symétrique, jamais un croissant tombant.
    /// `openness` écrase la hauteur AVANT rotation (clignement).
    static func fierceEyePath(center: CGPoint, len: CGFloat, ratio: CGFloat,
                              tilt: Double, inward: CGFloat,
                              openness: CGFloat) -> Path {
        let a = len / 2
        // Le facteur 1,37 : la hauteur réellement atteinte par les cubiques
        // ci-dessous vaut 1,37 h — on l'inverse pour que len/hauteur = ratio.
        let h = len / (ratio * 1.37)
        let cap = eyeOuterCap * h
        let raw: [CGPoint] = [
            CGPoint(x: -a, y: -cap),                       // 0 coin externe haut
            CGPoint(x: -0.62 * a, y: -1.16 * h),           // 1 ctrl haut
            CGPoint(x:  0.02 * a, y: -0.72 * h),           // 2 ctrl haut
            CGPoint(x:  a, y: 0),                          // 3 pointe interne
            CGPoint(x:  0.10 * a, y:  0.60 * h),           // 4 ctrl bas
            CGPoint(x: -0.62 * a, y:  1.02 * h),           // 5 ctrl bas
            CGPoint(x: -a, y:  cap)                        // 6 coin externe bas
        ]
        let ct = CGFloat(cos(tilt)), st = CGFloat(sin(tilt))
        let pts = raw.map { p -> CGPoint in
            let x = p.x * inward, y = p.y * openness
            // Rotation d'angle tilt·inward : la pointe plonge vers le nez.
            let rx = x * ct - y * st * inward
            let ry = x * st * inward + y * ct
            return CGPoint(x: center.x + rx, y: center.y + ry)
        }
        var path = Path()
        path.move(to: pts[0])
        path.addCurve(to: pts[3], control1: pts[1], control2: pts[2])
        path.addCurve(to: pts[6], control1: pts[4], control2: pts[5])
        path.closeSubpath()
        return path
    }

    // MARK: Données mesurées hors-app

    /// Format compact : "u,v,l;u,v,l;…", "|" entre les chemins. La compilation
    /// reste instantanée, le contenu est identique à un tableau littéral.
    static func decodeTriples(_ s: String) -> [SIMD3<Float>] {
        s.split(separator: ";").compactMap { tri in
            let c = tri.split(separator: ",")
            guard c.count == 3, let x = Float(c[0]), let y = Float(c[1]),
                  let z = Float(c[2]) else { return nil }
            return SIMD3<Float>(x, y, z)
        }
    }

    /// ~420 positions échantillonnées sur la LUMINANCE de la photo : chaque
    /// point scintille au prorata de sa lumière locale.
    static let glimmers: [SIMD3<Float>] = decodeTriples(NebulaData.glimmers)
    /// Les poussières RÉELLES détectées au voisinage des gros diablotins.
    static let impSpecks: [SIMD3<Float>] = decodeTriples(NebulaData.specks)
    /// ~380 chemins de dérive : spawn pondéré par la luminance (rejet si
    /// L < 0,25), avancée le long du TANGENT des crêtes (tenseur de
    /// structure), arrêt avant le noir. Aucune trajectoire ne traverse une
    /// zone noire ni ne coupe un filament, PAR CONSTRUCTION.
    static let driftPaths: [[SIMD3<Float>]] =
        NebulaData.drift.split(separator: "|").map { decodeTriples(String($0)) }
}

